mapper.select:
SELECT symbol_id, symbol
FROM symbol
WHERE exchange = #{exchange}

SELECT open_time AS ts, close_price AS v
FROM price_candle
WHERE symbol_id = #{symbolId}
  AND interval_code = #{interval}
  AND open_time >= #{since}
ORDER BY open_time

SELECT ts, oi_value_usd AS v
FROM open_interest
WHERE symbol_id = #{symbolId}
  AND period = #{period}
  AND ts >= #{since}
ORDER BY ts

SELECT funding_time AS ts, funding_rate AS v
FROM funding_rate
WHERE symbol_id = #{symbolId}
  AND funding_time >= #{since}
ORDER BY funding_time

SELECT ts, long_ratio AS v
FROM long_short_ratio
WHERE symbol_id = #{symbolId}
  AND ratio_type = #{ratioType}
  AND period = #{period}
  AND ts >= #{since}
ORDER BY ts

SELECT s.symbol, o.ts, o.oi_value_usd AS v
FROM open_interest o
JOIN symbol s ON s.symbol_id = o.symbol_id
WHERE o.period = #{period}
  AND o.ts >= #{since}
ORDER BY s.symbol, o.ts

SELECT r.*, s.symbol
FROM ai_report r
LEFT JOIN symbol s ON s.symbol_id = r.symbol_id
WHERE r.created_at >= #{since}
ORDER BY r.created_at DESC, r.report_id DESC
LIMIT #{limit}

SELECT m.*, s.symbol
FROM market_signal m
JOIN symbol s ON s.symbol_id = m.symbol_id
WHERE m.detected_at >= #{since}
ORDER BY m.detected_at DESC, m.signal_id DESC
LIMIT #{limit}

SELECT s.symbol, c.open_time AS ts, c.open_price, c.high_price, c.low_price, c.close_price
FROM price_candle c
JOIN symbol s ON s.symbol_id = c.symbol_id
WHERE c.interval_code = #{interval}
  AND c.open_time >= #{since}
ORDER BY s.symbol, c.open_time

SELECT s.symbol, l.ts, l.long_ratio AS v
FROM long_short_ratio l
JOIN symbol s ON s.symbol_id = l.symbol_id
WHERE l.ratio_type = #{ratioType}
  AND l.period = #{period}
  AND l.ts >= #{since}
ORDER BY s.symbol, l.ts

SELECT COUNT(*)
FROM market_signal
WHERE symbol_id = #{symbolId}
  AND signal_type = #{signalType}
  AND detected_at >= #{since}
